        let config_path = temp_dir.path().join("config.txt");

        // Write some sample data to the config file
        fs::write(
            &config_path,
            r"
# This is a comment
[section1]
key1 = value1
key2 = value2

[section2]
key3 = value3
key4 = value4
",
        )
        .unwrap();

        // Parse the config file
