use std::collections::HashMap;
use std::fs::File;
use std::io::{self, BufRead, BufReader};
use std::path::Path;

/// Parses a config file of `key = value` lines into a HashMap<String, String>.
///
/// Supports sections in the format [section], where keys under a section become `section.key`.
/// Skips blank lines and lines starting with `#`.
fn parse_config_file(path: &Path) -> Result<HashMap<String, String>, ConfigError> {
    let file = File::open(path)?;
    let reader = BufReader::new(file);

    let mut config_map = HashMap::new();
    let mut current_section = None;

    for line_result in reader.lines() {
        let line = line_result?;
        if line.trim().is_empty() || line.starts_with('#') {
            continue; // Skip empty lines and comments
        }

        if line.starts_with('[') && line.ends_with(']') {
            // Handle section header
            current_section = Some(line.trim_matches(|c: char| c == '[' || c == ']').to_string());
            continue;
        }

        let parts: Vec<&str> = line.splitn(2, '=').map(|part| part.trim()).collect();
        if parts.len() != 2 {
            return Err(ConfigError::InvalidFormat(line.to_string()));
        }

        let (key, value) = (parts[0].to_string(), parts[1].to_string());

        if let Some(section) = &current_section {
            config_map.insert(format!("{}.{}", section, key), value);
        } else {
            config_map.insert(key, value);
        }
    }

    Ok(config_map)
}

/// Custom error type for configuration parsing errors.
#[derive(Debug)]
pub enum ConfigError {
    Io(io::Error),
    InvalidFormat(String),
}

impl std::fmt::Display for ConfigError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            ConfigError::Io(e) => write!(f, "IO Error: {}", e),
            ConfigError::InvalidFormat(line) => write!(f, "Invalid format in line: {}", line),
        }
    }
}

impl std::error::Error for ConfigError {}

