use std::collections::VecDeque;
use std::fs;
use std::io;
use std::str::FromStr;

#[derive(Debug)]
struct TreeNode<T> {
    value: T,
    children: Vec<TreeNode<T>>,
}

impl<T> TreeNode<T> {
    fn level_order(&self) -> Vec<Vec<&T>> {
        let mut result = Vec::new();
        let mut queue = VecDeque::from([self]);

        while !queue.is_empty() {
            let current_size = queue.len();
            let mut level = Vec::with_capacity(current_size);

            for _ in 1..=current_size {
                let Some(node) = queue.pop_front() else { break };
                level.push(&node.value);
                queue.extend(&node.children);
            }

            result.push(level);
        }

        result
    }

    fn serialize(&self) -> Vec<String>
    where
        T: ToString,
    {
        let mut serialized = Vec::new();
        let mut stack = vec![self];

        while let Some(node) = stack.pop() {
            serialized.push(node.value.to_string());
            serialized.push(node.children.len().to_string());

            for child in node.children.iter().rev() {
                stack.push(child);
            }
        }

        serialized
    }

    fn deserialize(serialized: &[String], pos: &mut usize) -> Option<Self>
    where
        T: FromStr,
    {
        let value = serialized.get(*pos)?.parse().ok()?;
        let child_count: usize = serialized.get(*pos + 1)?.parse().ok()?;
        *pos += 2;

        let mut children = Vec::new();
        for _ in 0..child_count {
            children.push(Self::deserialize(serialized, pos)?);
        }

        Some(TreeNode { value, children })
    }

    fn save(&self, path: &str) -> io::Result<()>
    where
        T: ToString,
    {
        fs::write(path, self.serialize().join("\n"))
    }

    fn load(path: &str) -> Option<Self>
    where
        T: FromStr,
    {
        let text = fs::read_to_string(path).ok()?;
        let serialized: Vec<String> = text.lines().map(String::from).collect();
        Self::deserialize(&serialized, &mut 0)
    }
}

fn main() -> io::Result<()> {
    let root = TreeNode {
        value: "root".to_string(),
        children: vec![
            TreeNode {
                value: "a".to_string(),
                children: vec![
                    TreeNode { value: "a1".to_string(), children: vec![] },
                    TreeNode { value: "a2".to_string(), children: vec![] },
                ],
            },
            TreeNode {
                value: "b".to_string(),
                children: vec![TreeNode { value: "b1".to_string(), children: vec![] }],
            },
        ],
    };

    root.save("tree.txt")?;

    let Some(loaded) = TreeNode::<String>::load("tree.txt") else {
        println!("invalid tree file");
        return Ok(());
    };

    for level in loaded.level_order() {
        println!("{:?}", level);
    }

    Ok(())
}

use std::collections::HashMap;
use std::error::Error;

/// Custom error type for configuration parsing errors.
#[derive(Debug)]
enum ConfigError {
    InvalidLine(String),
}

impl std::fmt::Display for ConfigError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            ConfigError::InvalidLine(line) => write!(f, "Invalid line: {}", line),
        }
    }
}

impl Error for ConfigError {}

/// Parses a config file of `key = value` lines into a HashMap<String, String>.
///
/// Skips blank lines and lines starting with `#`.
/// Handles sections enclosed in square brackets.
fn parse_config_file(content: &str) -> Result<HashMap<String, String>, ConfigError> {
    let mut config_map = HashMap::new();
    let mut current_section = None;

    for line in content.lines() {
        if line.trim().is_empty() || line.starts_with('#') {
            continue; // Skip empty lines and lines starting with '#'
        } else if line.starts_with('[') && line.ends_with(']') {
            // Handle section header
            current_section = Some(line.trim_matches(|c| c == '[' || c == ']').to_string());
            continue;
        }

        let parts: Vec<&str> = line.split_once('=').ok_or_else(|| ConfigError::InvalidLine(line.to_string()))?;
        let key = parts[0].trim().to_string();
        let value = parts[1].trim().to_string();

        if let Some(section) = &current_section {
            config_map.insert(format!("{}.{}", section, key), value);
        } else {
            config_map.insert(key, value);
        }
    }

    Ok(config_map)
}

// Unit test for the parse_config_file function
#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_parse_config_file() {
        let config_content = r"
# This is a comment
key1 = value1
key2 = value2
key3 = value3
";

        let expected = [
            ("key1".to_string(), "value1".to_string()),
            ("key2".to_string(), "value2".to_string()),
            ("key3".to_string(), "value3".to_string()),
        ]
        .iter()
        .cloned()
        .collect::<HashMap<_, _>>();

        assert_eq!(parse_config_file(config_content), Ok(expected));
    }

    #[test]
    fn test_parse_config_file_with_whitespace() {
        let config_content = r"
key1 = value1  
key2= value2 
key3=value3
";

        let expected = [
            ("key1".to_string(), "value1".to_string()),
            ("key2".to_string(), "value2".to_string()),
            ("key3".to_string(), "value3".to_string()),
        ]
        .iter()
        .cloned()
        .collect::<HashMap<_, _>>();

        assert_eq!(parse_config_file(config_content), Ok(expected));
    }

    #[test]
    fn test_parse_config_file_with_invalid_line() {
        let config_content = r"
key1 = value1
invalid_line_without_equal_sign
key2 = value2
";

        assert_eq!(
            parse_config_file(config_content),
            Err(ConfigError::InvalidLine("invalid_line_without_equal_sign".to_string()))
        );
    }

    #[test]
    fn test_parse_config_file_with_sections() {
        let config_content = r"
[section1]
key1 = value1
key2 = value2

[section2]
key3 = value3
key4 = value4
";

        let expected = [
            ("section1.key1".to_string(), "value1".to_string()),
            ("section1.key2".to_string(), "value2".to_string()),
            ("section2.key3".to_string(), "value3".to_string()),
            ("section2.key4".to_string(), "value4".to_string()),
        ]
        .iter()
        .cloned()
        .collect::<HashMap<_, _>>();

        assert_eq!(parse_config_file(config_content), Ok(expected));
    }
}

