use std::collections::HashMap;
use std::fs::File;
use std::io::{self, BufRead, BufReader};
use std::path::Path;

/// Parses a config file of `key = value` lines into a HashMap<String, String>.
///
/// Skips blank lines and lines starting with `#`.
fn parse_config_file<P>(path: P) -> Result<HashMap<String, String>, ConfigError>
where
    P: AsRef<Path>,
{
    let file = File::open(path)?;
    let reader = BufReader::new(file);

    let mut config_map = HashMap::new();

    for line in reader.lines() {
        let line = line?;
        let line = line.trim();

        if line.is_empty() || line.starts_with('#') {
            continue;
        }

        let parts: Vec<&str> = line.split_once('=').ok_or(ConfigError::InvalidFormat)?;

        let key = parts[0].trim().to_string();
        let value = parts[1].trim().to_string();

        config_map.insert(key, value);
    }

    Ok(config_map)
}

/// Custom error enum for configuration parsing errors.
#[derive(Debug)]
pub enum ConfigError {
    Io(io::Error),
    InvalidFormat,
}

impl std::fmt::Display for ConfigError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            ConfigError::Io(e) => write!(f, "I/O Error: {}", e),
            ConfigError::InvalidFormat => write!(f, "Invalid format in config file"),
        }
    }
}

impl std::error::Error for ConfigError {}

