mod tests {
    use super::*;

    #[test]
    fn test_parse_config_file() {
        // Create a temporary config file for testing
        let temp_dir = tempfile::tempdir().unwrap();
        let config_path = temp_dir.path().join("config.txt");
        fs::write(
            &config_path,
            r"
# This is a comment
[section1]
key1 = value1
[section2]
key2 = value2
key3 = value3
",
        )
        .unwrap();

        // Parse the config file
        let config_map = parse_config_file(&config_path).unwrap();

        // Check the results
