    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ConfigError::InvalidLine(line) => write!(f, "Invalid line: {}", line),
            ConfigError::SectionWithoutKey(section) => write!(f, "Section without key: {}", section),
        }
    }
}

impl std::error::Error for ConfigError {}

// Function to parse a config file into a HashMap
pub fn parse_config_file(content: &str) -> Result<HashMap<String, String>, ConfigError> {
    let mut config_map = HashMap::new();
    let mut current_section = None;

    for line in content.lines() {
        // Skip empty lines and lines starting with '#'
        if line.trim().is_empty() || line.starts_with('#') {
            continue;
        }

        // Check for section header
        if line.starts_with('[') && line.ends_with(']') {
            current_section = Some(line.trim_matches(|c| c == '[' || c == ']').to_string());
            continue;
        }

        // Split the line into key-value pair
        let parts: Vec<&str> = line.split_once('=').ok_or_else(|| ConfigError::InvalidLine(line.to_string()))?;

        // Trim whitespace and insert into the map
        let key = parts[0].trim().to_string();
        let value = parts[1].trim().to_string();

        if let Some(section) = &current_section {
            let full_key = format!("{}.{}", section, key);
            config_map.insert(full_key, value);
        } else {
            config_map.insert(key, value);
        }
    }

    Ok(config_map)
}

