use std::collections::HashMap;
use std::fs::File;
use std::io::{self, BufRead};
use std::path::Path;

/// Custom error type for configuration parsing errors.
#[derive(Debug)]
enum ConfigError {
    Io(io::Error),
    ParseError(String),
}

impl std::fmt::Display for ConfigError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            ConfigError::Io(e) => write!(f, "IO error: {}", e),
            ConfigError::ParseError(msg) => write!(f, "Parse error: {}", msg),
        }
    }
}

impl std::error::Error for ConfigError {}

/// Parses a config file of `key = value` lines into a HashMap<String, String>.
///
/// Skips blank lines and lines starting with #.
fn parse_config_file(path: &str) -> Result<HashMap<String, String>, ConfigError> {
    let mut config_map = HashMap::new();

    let file = File::open(path).map_err(ConfigError::Io)?;
    let reader = io::BufReader::new(file);

    for line_result in reader.lines() {
        let line = line_result.map_err(ConfigError::Io)?;

        if line.trim().is_empty() || line.starts_with('#') {
            continue; // Skip empty lines and comments
        }

        let parts: Vec<&str> = line.splitn(2, '=').collect();
        if parts.len() != 2 {
            return Err(ConfigError::ParseError(format!("Invalid line: {}", line)));
        }

        let key = parts[0].trim().to_string();
        let value = parts[1].trim().to_string();

        config_map.insert(key, value);
    }

    Ok(config_map)
}

