use std::collections::HashMap;
use std::fs::File;
use std::io::{self, BufRead};
use std::path::Path;

/// Custom error type for configuration parsing errors.
#[derive(Debug)]
enum ConfigError {
    Io(io::Error),
    ParseError(String),
}

impl std::fmt::Display for ConfigError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            ConfigError::Io(e) => write!(f, "IO error: {}", e),
            ConfigError::ParseError(msg) => write!(f, "Parse error: {}", msg),
        }
    }
}

impl std::error::Error for ConfigError {}

/// Parses a config file of `key = value` lines into a HashMap<String, String>.
///
/// Supports sections denoted by [section] headers, where keys under a section become `section.key`.
///
/// Skips blank lines and lines starting with #.
fn parse_config_file(path: &str) -> Result<HashMap<String, String>, ConfigError> {
    let mut config_map = HashMap::new();
    let mut current_section = None;

    let file = File::open(path).map_err(ConfigError::Io)?;
    let reader = io::BufReader::new(file);

    for line_result in reader.lines() {
        let line = line_result.map_err(ConfigError::Io)?;

        if line.trim().starts_with('[') && line.trim().ends_with(']') {
            // Extract the section name
            let section_name = line.trim_start_matches('[').trim_end_matches(']').to_string();
            current_section = Some(section_name);
            continue;
        } else if line.trim().is_empty() || line.starts_with('#') {
            continue; // Skip empty lines and comments
        }

        let parts: Vec<&str> = line.splitn(2, '=').collect();
        if parts.len() != 2 {
            return Err(ConfigError::ParseError(format!("Invalid line: {}", line)));
        }

        let key = parts[0].trim().to_string();
        let value = parts[1].trim().to_string();

        if let Some(section) = &current_section {
            config_map.insert(format!("{}.{}", section, key), value);
        } else {
            config_map.insert(key, value);
        }
    }

    Ok(config_map)
}

// Unit test for the parse_config_file function
#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_parse_config_file() {
        let content = r"
# This is a comment
[section1]
key1 = value1
key2 = value2

[section2]
keyA = valueA
keyB = valueB
";

        let temp_dir = tempfile::tempdir().unwrap();
        let config_path = temp_dir.path().join("config.txt");
        std::fs::write(&config_path, content).unwrap();

        let result = parse_config_file(config_path.to_str().unwrap());
        assert!(result.is_ok());

        let config_map = result.unwrap();
        assert_eq!(config_map["section1.key1"], "value1");
        assert_eq!(config_map["section1.key2"], "value2");
        assert_eq!(config_map["section2.keyA"], "valueA");
        assert_eq!(config_map["section2.keyB"], "valueB");
    }
}

