use std::collections::HashMap;

/// Custom error type for configuration parsing errors.
#[derive(Debug)]
enum ConfigError {
    InvalidFormat(String),
    MissingSectionHeader(String),
}

impl std::fmt::Display for ConfigError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            ConfigError::InvalidFormat(msg) => write!(f, "Invalid format: {}", msg),
            ConfigError::MissingSectionHeader(section) => write!(f, "Missing section header for key: {}", section),
        }
    }
}

impl std::error::Error for ConfigError {}

/// Parses a config file of `key = value` lines into a HashMap<String, String>,
/// handling sections prefixed by [section].
///
/// Blank lines and lines starting with `#` are ignored.
fn parse_config_file(content: &str) -> Result<HashMap<String, String>, ConfigError> {
    let mut config_map = HashMap::new();
    let mut current_section = None;

    for line in content.lines() {
        // Skip empty lines and lines starting with '#'
        if line.trim().is_empty() || line.starts_with('#') {
            continue;
        }

        // Check for section header
        if line.starts_with('[') && line.ends_with(']') {
            current_section = Some(line.trim_matches(|c| c == '[' || c == ']').to_string());
            continue;
        }

        // Split the line into key and value
        let parts: Vec<&str> = line.split_once('=').ok_or_else(|| ConfigError::InvalidFormat(line.to_string()))?;
        let key = parts[0].trim().to_string();
        let value = parts[1].trim().to_string();

        // Handle keys within sections
        if let Some(section) = &current_section {
            let full_key = format!("{}.{}", section, key);
            config_map.insert(full_key, value);
        } else {
            config_map.insert(key, value);
        }
    }

    Ok(config_map)
}

