use std::collections::HashMap;
use std::error::Error;

/// Custom error type for configuration parsing errors.
#[derive(Debug)]
enum ConfigError {
    InvalidFormat,
    Io(std::io::Error),
}

impl std::fmt::Display for ConfigError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            ConfigError::InvalidFormat => write!(f, "Invalid configuration format"),
            ConfigError::Io(e) => write!(f, "IO error: {}", e),
        }
    }
}

impl Error for ConfigError {}

/// Parses a config file of `key = value` lines into a HashMap<String, String>,
/// supporting sections.
fn parse_config_file(content: &str) -> Result<HashMap<String, String>, ConfigError> {
    let mut config_map = HashMap::new();
    let mut current_section = None;

    for line in content.lines() {
        if line.trim().is_empty() || line.starts_with('#') {
            continue; // Skip empty lines and lines starting with #
        }

        if line.starts_with('[') && line.ends_with(']') {
            // Handle section header
            current_section = Some(line.trim_matches(|c| c == '[' || c == ']').to_string());
            continue;
        }

        let parts: Vec<&str> = line.splitn(2, '=').collect();
        if parts.len() != 2 {
            return Err(ConfigError::InvalidFormat);
        }

        let key = parts[0].trim().to_string();
        let value = parts[1].trim().to_string();

        if let Some(section) = &current_section {
            config_map.insert(format!("{}.{}", section, key), value);
        } else {
            config_map.insert(key, value);
        }
    }

    Ok(config_map)
}

// Unit test for the parse_config_file function
#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_parse_config_file() {
        let config_content = r"
# This is a comment
key1 = value1
key2 = value2
key3 = value3
";

        let expected: HashMap<String, String> = [
            ("key1".to_string(), "value1".to_string()),
            ("key2".to_string(), "value2".to_string()),
            ("key3".to_string(), "value3".to_string()),
        ]
        .iter()
        .cloned()
        .collect();

        assert_eq!(parse_config_file(config_content), Ok(expected));
    }

    #[test]
    fn test_parse_config_file_invalid_format() {
        let config_content = r"key1=value1=value2";
        assert_eq!(parse_config_file(config_content), Err(ConfigError::InvalidFormat));
    }

    #[test]
    fn test_parse_config_file_skip_blank_lines_and_comments() {
        let config_content = r"
key1 = value1
# This is a comment
key2 = value2
";
        let expected: HashMap<String, String> = [
            ("key1".to_string(), "value1".to_string()),
            ("key2".to_string(), "value2".to_string()),
        ]
        .iter()
        .cloned()
        .collect();

        assert_eq!(parse_config_file(config_content), Ok(expected));
    }

    #[test]
    fn test_parse_config_file_with_sections() {
        let config_content = r"
[section1]
key1 = value1
key2 = value2

[section2]
key3 = value3
key4 = value4
";

        let expected: HashMap<String, String> = [
            ("section1.key1".to_string(), "value1".to_string()),
            ("section1.key2".to_string(), "value2".to_string()),
            ("section2.key3".to_string(), "value3".to_string()),
            ("section2.key4".to_string(), "value4".to_string()),
        ]
        .iter()
        .cloned()
        .collect();

        assert_eq!(parse_config_file(config_content), Ok(expected));
    }
}

